function impella(config){
 const rv=config.id==='impella-rv';
 const positional=['impella-shallow','impella-deep'].includes(config.id);
 const c={...config,pod:'delta',patient:config.patient||'Patient D-04 · 61 years · 80 kg · post-MI cardiogenic shock',device:positional?'Impella 5.5 · right axillary access':'Impella CP · femoral access',
  vitals:config.vitals||{HR:118,MAP:61,SpO2:96,UO:20},
  targets:'Case order: systemic MAP ≥65 mmHg; reassess perfusion after every support change.',
  orders:commonImpellaOrders,labs:impellaLabs,
  assessments:[
   obs('perfusion','Assess the patient first',config.perfusion||'Cool hands, delayed capillary refill and increased restlessness. Arterial line MAP 61 mmHg. Urine: 20 mL over the previous hour.','Use mentation, skin, BP and urine together. Device flow is not total cardiac output.'),
   obs('access','Inspect access, limb & tubing',config.access||'Recorded catheter mark unchanged. Dressing dry, no expanding hematoma. Distal pulses present; foot warm. Tubing supported without a visible kink.','Compare with the handoff mark. Check bleeding and distal perfusion before attributing every alarm to volume.'),
   obs('filling','Review filling & fluid balance',config.filling,'CVP is a pressure influenced by many factors. Combine the trend with RV assessment, volume balance, lungs and echo.'),
   obs('waves','Compare Ao, estimated LV & motor current',config.waveFinding,'Red is sensed placement pressure. White is calculated LV pressure. Green is motor current, not ECG. Low native pulsatility can also flatten green.')
  ],
  goals:[goal('report','Receive the baseline report'),goal('perfusion','Assess systemic perfusion'),goal('access','Inspect access & distal circulation'),goal('filling','Review filling and fluid balance'),goal('waves','Interpret the pressure pattern'),goal('orders','Reconcile orders & due labs'),goal('reduce','Respond to the alarm'),goal('notify','Escalate with the key findings'),goal('echo','Obtain team / echo assessment'),goal('resolve','Follow the ordered cause-specific plan'),goal('reassess','Reassess the patient and support'),goal('document','Document and hand off')],
  actions:[
   action('reduce',positional?'Follow position-alarm order: P2':'Reduce support by 1–2 P-levels per case order','Trained RN / case protocol',positional?'P2 selected. Support is limited while the team checks position. Continue watching systemic perfusion.':'P9 → P7. Suction eases, but the cause still needs assessment. Do not simply leave the patient with less support and move on.',{effect:{monitor:{p:positional?2:7,flow:positional?1.2:2.7},alarm:positional?config.alarm:'SUCTION · assess cause'},minutes:0}),
   action('notify','Call the provider / shock team now','RN escalation',config.notify,{minutes:0}),
   action('echo','Request / review urgent echo with the team','Team assessment',config.echo,{requires:['notify']}),
   action('resolve',config.resolveLabel,'Prescribed / specialist plan',config.resolution,{requires:positional?['reduce','notify','echo']:rv?['reduce','perfusion','filling','orders','notify','echo']:['reduce','perfusion','filling','orders','notify'],effect:config.resolveEffect||{},minutes:positional?8:15}),
   action('reassess','Recheck perfusion, waves, access and support','RN reassessment',config.reassessment,{requires:['resolve'],effect:config.finalEffect||{},minutes:5}),
   action('blindfluid','Give a large fluid bolus without reassessment','Unsafe shortcut','A low flow or suction alarm is not a fluid prescription. Verify filling, bleeding, congestion, RV function and the active order.',{unsafe:true}),
   action('pull','Reposition the catheter independently','Unsafe shortcut','Stop. Catheter manipulation belongs to a credentialed operator using the applicable imaging/device procedure.',{unsafe:true}),
   action('silence','Silence the alarm and leave the patient','Unsafe shortcut','Silencing does not treat suction or malposition. Persistent suction can reduce support and injure blood cells.',{unsafe:true})
  ],
  debrief:config.debrief,
  exampleNote:config.exampleNote
 };
 if(rv){c.actions.splice(2,0,action('papi','Calculate PAPi from the current pressures','Reasoning tool','(28 − 22) ÷ 18 = 0.33. In this context the low value supports concern for RV dysfunction; it is not a stand-alone diagnosis.',{calculation:{prompt:'PA 28/22 mmHg; mean RA/CVP 18 mmHg. PAPi = ?',expected:1/3,tolerance:.02,units:'',formula:'(PA systolic − PA diastolic) ÷ mean RA pressure'}}));c.goals.splice(5,0,goal('papi','Calculate PAPi and interpret it in context'));}
 return c;
}

